package com.hmdp.ai.infrastructure.mcp;import com.hmdp.ai.domain.mcp.*;import org.springframework.stereotype.Component;@Component public class McpToolSyncService {private final McpToolDiscoveryService discovery;private final McpRepository repository;public McpToolSyncService(McpToolDiscoveryService discovery,McpRepository repository){this.discovery=discovery;this.repository=repository;}public int sync(McpServer server,String actor){return repository.syncTools(server,discovery.discover(server),actor);}}
